# frozen_string_literal: true

module RuboCop
  module Cop
    # This class autocorrects `if...then` structures to a multiline `if` statement
    class IfThenCorrector
      DEFAULT_INDENTATION_WIDTH = 2

      def initialize(if_node, indentation: nil)
        @if_node = if_node
        @indentation = indentation || DEFAULT_INDENTATION_WIDTH
      end

      def call(corrector)
        corrector.replace(if_node, replacement)
      end

      def accepted_if?(ending, cop)
        node = if_node
        config = cop.config

input.newString:
def accepted_form?(node, ending: false)
  return true if assigned_lvar_used_in_if_branch?(node)

  IfThenCorrector.new(node).accepted_if?(ending, self)
end

def assigned_lvar_used_in_if_branch?(node)
  return false unless (if_branch = node.if_branch)

  assigned_lvars_in_condition = node.condition.each_descendant(:lvasgn).map do |lvasgn|
    lvar_name, = *lvasgn
    lvar_name.to_s
  end
  used_lvars_in_branch = if_branch.each_descendant(:lvar).map(&:source) || []

  (assigned_lvars_in_condition & used_lvars_in_branch).any?
end

